export function predict(model: Model, vector: number[], costs: Matrix | null = null): Prediction {
  const h = (model.features.length * Math.log(2 * Math.PI)) / 2;
  const distances: number[] = [];
  const scores: number[] = [];
  for (const g of model.classes) {
    const q = quadratic(
      g.lower,
      vector.map((v, j) => v - g.mean[j]),
    );
    distances.push(q);
    scores.push(Math.log(g.prior) - h - g.logDeterminant / 2 - q / 2);
  }
  let predicted = 0;
  for (let k = 1; k < scores.length; k++) if (scores[k] > scores[predicted]) predicted = k;
  const maximum = scores[predicted];
  const exponentials = scores.map((g) => Math.exp(g - maximum));
  let sum = 0;
  for (const e of exponentials) sum += e;
  const posterior = exponentials.map((e) => e / sum);
  const logPosterior = scores.map((g) => g - maximum - Math.log(sum));
  let decision = predicted;
  if (costs) {
    let least = Infinity;
    for (let b = 0; b < scores.length; b++) {
      let risk = 0;
      for (let k = 0; k < scores.length; k++) risk += posterior[k] * costs[k][b];
      if (risk < least) {
        least = risk;
        decision = b;
      }
    }
  }
  return {
    predicted,
    posterior,
    logPosterior,
    confidence: Math.max(...posterior),
    decision,
    distances,
  };
}
export const predictRow = (model: Model, row: Row, costs: Matrix | null = null) =>
  predict(
    model,
    model.features.map((f) => row.values[f]),
    costs,
  );
export function confusion(rows: Row[], predicted: number[], count: number) {
  const table: number[][] = Array.from({ length: count }, () => Array(count).fill(0));
  rows.forEach((r, i) => table[r.class][predicted[i]]++);
const predictions = (v: Prediction[]) => v.map((p) => p.predicted);
const classify = (model: Model, rows: Row[], costs: number[][] | null = null) =>
  rows.map((r) => predictRow(model, r, costs));
function evaluateModel(d: Data, type: ModelType, results: Prediction[]) {
  const predicted = predictions(results);
  const m = confusion(d.test, predicted, d.classes.length);
  const n = d.test.length;
  d.test.forEach((r, i) => {
    if (r.class !== predicted[i]) {
      lines.push(
        fields(
          'error',
          r.id,
          'actual',
          r.label,
          'predicted',
          d.classes[predicted[i]],
          'confidence',
          real(results[i].confidence),
        ),
      );
    }
  });
  for (const t of d.settings.reject) {
    let accepted = 0;
    let correct = 0;
    d.test.forEach((r, i) => {
      if (results[i].confidence >= t) {
        accepted++;
        correct += Number(r.class === predicted[i]);
      }
    });
    lines.push(
      fields(
        'reject',
        real(t),
        'accepted',
        accepted,
        'coverage',
        ratio(accepted, n),
        'accuracy',
        ratio(correct, accepted),
      ),
    );
  }
  const ensemble = d.test.map((_, r) => {
    const p = d.classes.map((__, k) => {
      let sum = 0;
      for (let m = 0; m < 3; m++) sum += results[m][r].posterior[k];
      return sum / 3;
    });
    let best = 0;
    for (let k = 1; k < p.length; k++) if (p[k] > p[best]) best = k;
    return best;
  });
  results.forEach((model, i) => {
    let arg = 0;
    let decision = 0;
    let changed = 0;
    let correct = 0;
    d.test.forEach((r, j) => {
      const p = model[j];
      arg += d.costs[r.class][p.predicted];
      decision += d.costs[r.class][p.decision];
      changed += Number(p.predicted !== p.decision);
      correct += Number(p.decision === r.class);
    });
    costs.push(
      fields(
        MODELS[i],
        'argmax_total',
        real(arg),
        'decision_total',
        real(decision),
        'changed',
        changed,
        'decision_accuracy',
        ratio(correct, d.test.length),
      ),
    );
  });
  const results = models.map((m) => classify(m, d.test, d.costs));
